#include "full_dive/touch_chip/AvatarSomatotopicSurfaceMap.h"
#include <algorithm>
#include <cmath>
namespace dnxr { float AvatarSomatotopicSurfaceMap::clamp01(float v){return std::max(0.0f,std::min(1.0f,v));} AvatarSomatotopicSurfaceFrame AvatarSomatotopicSurfaceMap::map(const std::vector<VirtualContactPatch>& patches) const { AvatarSomatotopicSurfaceFrame out; float right=0,left=0; for(const auto& p:patches){ SomatotopicContactCell c; c.region=p.region; c.pressure01=clamp01(p.pressure01); c.area01=clamp01(p.area01); c.slip01=clamp01(p.slip01); c.texture01=clamp01(p.vibrationHz/250.0f); c.temperature01=clamp01(p.temperature01); c.confidence01=clamp01(c.area01+c.pressure01); out.totalLoad01=clamp01(out.totalLoad01+c.pressure01*c.area01); if(p.region==BodyRegion::RightHand) right=std::max(right,c.pressure01); if(p.region==BodyRegion::LeftHand) left=std::max(left,c.pressure01); out.cells.push_back(c);} out.asymmetry01=clamp01(std::fabs(right-left)); out.overloadRisk01=out.totalLoad01>0.75f?out.totalLoad01:0.0f; return out;} NeuralTouchVector AvatarSomatotopicSurfaceMap::toTouchVector(const AvatarSomatotopicSurfaceFrame& f) const { NeuralTouchVector out; out.contactPressure01=f.totalLoad01; out.bodyCollision01=f.overloadRisk01; out.somatosensoryConfidence01=clamp01(1.0f-f.asymmetry01); out.painBlocked01=out.burnBlocked01=out.crushBlocked01=out.shockBlocked01=1.0f; for(const auto& c:f.cells){ out.contactArea01=std::max(out.contactArea01,c.area01); out.slip01=std::max(out.slip01,c.slip01); out.vibrationTexture01=std::max(out.vibrationTexture01,c.texture01); if(c.region==BodyRegion::RightHand) out.rightHandContact01=std::max(out.rightHandContact01,c.pressure01); if(c.region==BodyRegion::LeftHand) out.leftHandContact01=std::max(out.leftHandContact01,c.pressure01); if(c.region==BodyRegion::Feet) out.footGroundContact01=std::max(out.footGroundContact01,c.pressure01); } return out;} }
